t:16px;color:#1E1E1E;word-wrap:break-word;">SRV100000004</td><td valign="top" style="border:1px solid #B9C1CA;padding:5px 8px;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:16px;color:#1E1E1E;word-wrap:break-word;">Service Request</td><td valign="top" style="border:1px solid #B9C1CA;padding:5px 8px;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:16px;color:#1E1E1E;word-wrap:break-word;">Cancelled request</td><td valign="top" style="border:1px solid #B9C1CA;padding:5px 8px;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:16px;color:#1E1E1E;word-wrap:break-word;">Sam Example</td><td valign="top" style="border:1px solid #B9C1CA;padding:5px 8px;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:16px;color:#1E1E1E;word-wrap:break-word;">EXAMPLE_NETW&#8203;ORK</td><td valign="top" style="border:1px solid #B9C1CA;padding:5px 8px;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:16px;color:#1E1E1E;word-wrap:break-word;">Cancelled</td></tr></tbody></table></td></tr><tr><td style="padding:28px 32px 0 32px;font-family:Arial,Helvetica,sans-serif;font-size:13px;line-height:20px;color:#1E1E1E;"><p style="font-family:Arial,Helvetica,sans-serif">Best regards,<br>Alex Example</p><p style="font-family:Arial,Helvetica,sans-serif"><img src="cid:bmc-signature-1@local.invalid" alt="Example logo" width="48" height="48" style="max-width:100%;height:auto"></p></td></tr><tr><td style="padding:20px 32px 24px 32px;"><table role="presentation" width="736" cellpadding="0" cellspacing="0" border="0" style="width:736px;border-collapse:collapse;"><tbody><tr><td bgcolor="#F6F7F9" style="background-color:#F6F7F9;border:1px solid #D5DADF;padding:10px 12px;font-family:Arial,Helvetica,sans-serif;font-size:11px;line-height:16px;color:#59636E;">This is an automated report generated from BMC Helix ITSM. Figures cover tickets for 2026-11-10 (SGT) and exclude monitoring events. This email is intended only for the named recipients; if you received it in error, please notify the sender and delete it.</td></tr></tbody></table></td></tr><tr><td height="4" bgcolor="#2E3D4F" style="height:4px;background-color:#2E3D4F;font-size:1px;line-height:4px;mso-line-height-rule:exactly;">&nbsp;</td></tr></tbody></table></body></html>
'@
$images = @(
    @{ Name = 'bmc-signature-1.png'; ContentId = 'bmc-signature-1@local.invalid'; Base64 = 'iVBORw0KGgoAAAANSUhEUgAAADAAAAAwCAIAAADYYG7QAAAAOUlEQVR42u3OMQ0AAAgDsElENrLmgnA0qYBmJ69ESEhISEhISEhISEhISEhISEhISEhISEhISOhOATtB2IifDkUWAAAAAElFTkSuQmCC' }
)
$temporaryFiles = New-Object System.Collections.Generic.List[string]
try {
    $outlook = New-Object -ComObject Outlook.Application
    $mail = $outlook.CreateItem(0) # 0 = olMailItem
    $mail.BodyFormat = 2 # 2 = olFormatHTML
    $mail.To = 'team@example.com; lead@example.net'
    $mail.CC = 'manager@example.org'
    $mail.BCC = ''
    $mail.Subject = 'Daily BMC Ticket Report – 2026-11-10'
    $mail.HTMLBody = $html
    foreach ($image in $images) {
        $extension = if ($image.Name.EndsWith(".jpg")) { ".jpg" } else { ".png" }
        $tempFile = Join-Path ([IO.Path]::GetTempPath()) ("BMC-Mail-" + [Guid]::NewGuid().ToString("N") + $extension)
        [IO.File]::WriteAllBytes($tempFile, [Convert]::FromBase64String($image.Base64))
        [void] $temporaryFiles.Add($tempFile)
        $attachment = $mail.Attachments.Add($tempFile, 1, 1, $image.Name)
        $attachment.PropertyAccessor.SetProperty("http://schemas.microsoft.com/mapi/proptag/0x3712001F", [string] $image.ContentId)
        try { $attachment.PropertyAccessor.SetProperty("http://schemas.microsoft.com/mapi/proptag/0x7FFE000B", $true) } catch {}
    }
    $mail.Save() # Saves to the active Outlook profile Drafts folder
    $target = [IO.Path]::ChangeExtension($PSCommandPath, ".msg")
    $stem = [IO.Path]::Combine([IO.Path]::GetDirectoryName($target), [IO.Path]::GetFileNameWithoutExtension($target))
    $index = 1
    while ([IO.File]::Exists($target)) { $target = $stem + " (" + $index + ").msg"; $index++ }
    $mail.SaveAs($target, 9) # 9 = olMSGUnicode; editable in Classic Outlook
    $mail.Display($false) # Opens compose window for manual review and sending
    Write-Host ("Unsent draft opened in Classic Outlook; native .msg saved to " + $target)
} catch {
    Write-Host ("Could not create the Classic Outlook draft: " + $_.Exception.Message) -ForegroundColor Red
    [void] (Read-Host "Press Enter to close")
    exit 1
} finally {
    foreach ($path in $temporaryFiles) { Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue }
}
